// The importer keeps its own copy of the store's design tokens (src/styles/tokens.css) so it builds on its own, wherever
// it is cloned. The copy is generated by the store repo (design-tokens/, tokens.json -> dist/tokens.css).
//
//   npm run tokens:sync    refresh the copy from the store repo
//   npm run tokens:check   exit 1 if the copy is out of date (skipped when the store repo is not around)
//
// The store repo is found through DESIGN_TOKENS_DIR, else ../accessories-store-system/design-tokens (next to this project),
// else ../design-tokens (this project inside the store repo, as a submodule).
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const target = join(root, 'src', 'styles', 'tokens.css')
const checking = process.argv.includes('--check')

const candidates = [process.env.DESIGN_TOKENS_DIR, join(root, '..', 'accessories-store-system', 'design-tokens'), join(root, '..', 'design-tokens')]
const source = candidates.filter(Boolean).map((dir) => join(dir, 'dist', 'tokens.css')).find(existsSync)

if (!source) {
  const message = 'design tokens of the store repo not found (set DESIGN_TOKENS_DIR to its design-tokens folder)'
  if (checking) {
    console.log(`tokens: skipped, ${message}`)
    process.exit(0)
  }
  console.error(`tokens: ${message}`)
  process.exit(1)
}

const header = `/* COPY of the store's shared design tokens (accessories-store-system/design-tokens/dist/tokens.css).
   Do not edit here: change tokens.json in the store repo, build it there, then run \`npm run tokens:sync\` in this project. */
`
const wanted = header + readFileSync(source, 'utf8')
const current = existsSync(target) ? readFileSync(target, 'utf8') : ''

if (checking) {
  if (current === wanted) console.log('tokens: up to date')
  else {
    console.error('tokens: src/styles/tokens.css is out of date, run `npm run tokens:sync`')
    process.exit(1)
  }
} else {
  writeFileSync(target, wanted)
  console.log(current === wanted ? 'tokens: already up to date' : `tokens: copied from ${source}`)
}
